class Solution {public:vector<int> permute(int n,long long k){vector<int>od,ev;for(int i=1;i<=n;++i)(i%2?od:ev).push_back(i);vector<long long>fact(n+1,1);const long long LIM=4000000000000000000LL;for(int i=1;i<=n;++i)fact[i]=fact[i-1]>LIM/i?LIM:fact[i-1]*i;
 auto mul=[&](long long a,long long b){return a>LIM/b?LIM:a*b;};vector<int>ans;int prev=-1;
 for(int pos=0;pos<n;++pos){bool found=false;for(int x=1;x<=n;++x){if((prev!=-1&&x%2==prev%2))continue;vector<int>&v=x%2?od:ev;auto it=find(v.begin(),v.end(),x);if(it==v.end())continue;
 int o=od.size()-(x%2),e=ev.size()-(x%2==0);int rem=n-pos-1;int nextParity=1-x%2;
 bool valid=(rem==0)||(nextParity?o==(rem+1)/2&&e==rem/2:e==(rem+1)/2&&o==rem/2);long long ways=valid?mul(fact[o],fact[e]):0;
 if(k>ways){k-=ways;continue;}ans.push_back(x);v.erase(it);prev=x;found=true;break;
 }if(!found)return {}; }return ans;}};
